import sys

def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    a = [int(x) for x in data[2:2 + n]]
    cnt = {}
    res = []
    for i in range(n):
        cnt[a[i]] = cnt.get(a[i], 0) + 1
        if i >= m:
            y = a[i - m]
            cnt[y] -= 1
            if cnt[y] == 0:
                del cnt[y]
        if i >= m - 1:
            res.append(len(cnt))
    print(' '.join(map(str, res)))

main()

