def gen(rng):
    def fmt(m, a):
        return str(len(a)) + ' ' + str(m) + '\n' + ' '.join(map(str, a))
    tests = [fmt(1, [4]), fmt(1, [1, 2, 3]), fmt(3, [2, 2, 2]), fmt(2, [1, 2, 1, 2, 1]), fmt(4, [10**9, 1, 10**9, 1])]
    for n in (3, 5, 8, 12, 20, 30):
        for _ in range(3):
            m = rng.randint(1, n)
            tests.append(fmt(m, [rng.randint(1, rng.choice([2, 4, 10])) for _ in range(n)]))
    n = 10**5
    tests.append(fmt(50000, [rng.randint(1, 10**9) for _ in range(n)]))
    tests.append(fmt(50000, [rng.randint(1, 3000) for _ in range(n)]))
    tests.append(fmt(n, [rng.randint(1, 10**9) for _ in range(n)]))
    tests.append(fmt(1, [rng.randint(1, 5) for _ in range(n)]))
    tests.append(fmt(30000, [i % 20000 + 1 for i in range(n)]))
    return tests

